    const to = new Int32Array(2 * n);
    const next = new Int32Array(2 * n);
    let edgeCount = 0;

    function addEdge(u, v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        next[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    for (let i = 0; i < n - 1; i++) {
        const u = readInt();
        const v = readInt();
        addEdge(u, v);
    }

    // BFS to establish parent-child relationships and order
    const order = new Int32Array(n);
    const parent = new Int32Array(n + 1).fill(0);
    const visited = new Uint8Array(n + 1);

    let headQueue = 0;
    let tailQueue = 0;

    order[tailQueue++] = 1;
    visited[1] = 1;

    while (headQueue < tailQueue) {
        const u = order[headQueue++];
        for (let e = head[u]; e !== -1; e = next[e]) {
            const v = to[e];
            if (!visited[v]) {
                visited[v] = 1;
                parent[v] = u;
                order[tailQueue++] = v;
            }
        }
    }

    const size = new Int32Array(n + 1).fill(1);
    let minDiff = n;

    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        const p = parent[u];
        if (p !== 0) {
            size[p] += size[u];
            const diff = Math.abs(n - 2 * size[u]);
            if (diff < minDiff) {
                minDiff = diff;
            }
        }
    }

    console.log(minDiff);
}

